1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Maple Street Bakery</title>
7	<style>
8	  :root {
9	    --flour: #E6ECEF;
10	    --ink: #241B2F;
11	    --maple: #B5301C;
12	    --crust: #E3A02B;
13	    --paper: #FFFFFF;
14	    --display: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
15	    --body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  * { box-sizing: border-box; }
18	  html { scroll-behavior: smooth; }
19	  body {
20	    margin: 0;
21	    background: var(--flour);
22	    color: var(--ink);
23	    font: 1.0625rem/1.6 var(--body);
24	  }
25	  a { color: inherit; }
26	  :focus-visible { outline: 3px solid var(--maple); outline-offset: 3px; }
27	
28	  .wrap { width: min(100% - 2rem, 62rem); margin-inline: auto; }
29	
30	  /* top bar */
31	  header.bar { padding-block: 1.25rem; }
32	  header.bar .wrap { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; }
33	  .brand { font: 700 1.25rem var(--display); text-decoration: none; }
34	  nav { display: flex; gap: 1.5rem; }
35	  nav a { text-decoration: none; font-weight: 600; padding-block: .25rem; border-bottom: 2px solid transparent; }
36	  nav a:hover { border-color: var(--maple); }
37	
38	  /* hero */
39	  .hero { padding-block: clamp(2.5rem, 8vw, 6rem) clamp(3rem, 8vw, 5.5rem); }
40	  .hero h1 {
41	    margin: 0;
42	    font: 900 clamp(4rem, 17vw, 12rem)/.85 var(--display);
43	    letter-spacing: -.045em;
44	    color: var(--maple);
45	    animation: rise .9s cubic-bezier(.2,.8,.2,1) both;
46	  }
47	  .hero h1 span { display: block; color: var(--ink); font-size: .32em; letter-spacing: -.02em; margin-top: .35em; }
48	  .hero-row { display: flex; flex-wrap: wrap; gap: 1rem 2rem; align-items: center; margin-top: 2rem; }
49	  .hero p { margin: 0; max-width: 34ch; font-size: 1.25rem; }
50	  .status {
51	    display: inline-flex; align-items: center; gap: .6rem;
52	    background: var(--ink); color: var(--paper);
53	    padding: .55rem 1rem; border-radius: 99px; font-weight: 600; font-size: .95rem;
54	  }
55	  .status::before { content: ""; width: .65rem; height: .65rem; border-radius: 50%; background: var(--crust); }
56	  .status.open::before { background: #7FD08A; }
57	  @keyframes rise { from { opacity: 0; transform: translateY(1.5rem) rotate(-1deg); } to { opacity: 1; transform: none; } }
58	
59	  /* sections */
60	  section { padding-block: clamp(2.5rem, 6vw, 4.5rem); scroll-margin-top: 1rem; }
61	  h2 { margin: 0 0 1.5rem; font: 800 clamp(2rem, 5vw, 3rem)/1.05 var(--display); letter-spacing: -.02em; }
62	
63	  .band { background: var(--ink); color: var(--paper); }
64	  .band :focus-visible { outline-color: var(--crust); }
65	
66	  /* menu ledger */
67	  #menu ul { list-style: none; margin: 0; padding: 0; max-width: 40rem; }
68	  #menu li { display: flex; align-items: baseline; gap: .75rem; padding-block: .9rem; font: 600 1.5rem var(--display); }
69	  #menu li::after { content: ""; order: 1; flex: 1; border-bottom: 2px dotted currentColor; opacity: .4; transform: translateY(-.25em); }
70	  #menu li .price { order: 2; font-variant-numeric: tabular-nums; color: var(--crust); }
71	
72	  /* order */
73	  .order-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr)); gap: 1rem; }
74	  .order-grid button {
75	    font: 700 1.1rem var(--display);
76	    text-align: left;
77	    padding: 1.25rem;
78	    background: var(--paper);
79	    color: var(--ink);
80	    border: 2px solid var(--ink);
81	    border-radius: 6px;
82	    cursor: pointer;
83	    box-shadow: 5px 5px 0 var(--ink);
84	    transition: transform .12s, box-shadow .12s;
85	  }
86	  .order-grid button small { display: block; font: 500 .9rem var(--body); opacity: .7; margin-top: .2rem; }
87	  .order-grid button:hover { transform: translate(-2px,-2px); box-shadow: 7px 7px 0 var(--ink); }
88	  .order-grid button:active { transform: translate(4px,4px); box-shadow: 1px 1px 0 var(--ink); }
89	  .tally { margin-top: 2rem; font-size: 1.25rem; }
90	  .tally span { display: inline-block; min-width: 2ch; font: 900 2.5rem/1 var(--display); color: var(--maple); vertical-align: -.1em; }
91	
92	  /* newsletter */
93	  #news form { display: flex; flex-wrap: wrap; gap: .75rem; max-width: 34rem; }
94	  #news input {
95	    flex: 1 1 14rem; font: inherit; padding: .85rem 1rem;
96	    border: 2px solid var(--ink); border-radius: 6px; background: var(--paper); color: var(--ink);
97	  }
98	  #news form button {
99	    font: 700 1rem var(--body); padding: .85rem 1.5rem; cursor: pointer;
100	    background: var(--maple); color: var(--paper); border: 2px solid var(--maple); border-radius: 6px;
101	  }
102	  #news form button:hover { background: var(--ink); border-color: var(--ink); }
103	  #news-msg { min-height: 1.6em; margin: 1rem 0 0; font-weight: 600; }
104	
105	  footer { padding-block: 2rem 3rem; font-size: .95rem; }
106	
107	  @media (prefers-reduced-motion: reduce) {
108	    html { scroll-behavior: auto; }
109	    .hero h1 { animation: none; }
110	    .order-grid button { transition: none; }
111	  }
112	</style>
113	</head>
114	<body>
115	
116	<header class="bar">
117	  <div class="wrap">
118	    <a class="brand" href="#top">Maple Street Bakery</a>
119	    <nav aria-label="Main">
120	      <a href="#menu">Menu</a>
121	      <a href="#order">Order</a>
122	      <a href="#news">Newsletter</a>
123	    </nav>
124	  </div>
125	</header>
126	
127	<main id="top">
128	  <div class="hero">
129	    <div class="wrap">
130	      <h1>Bread by 7.<span>Maple Street Bakery</span></h1>
131	      <div class="hero-row">
132	        <p>We bake bread every morning. Open 7am to 3pm, Tuesday to Sunday.</p>
133	        <span class="status" id="status" role="status">Open Tuesday to Sunday, 7am to 3pm</span>
134	      </div>
135	    </div>
136	  </div>
137	
138	  <section id="menu" class="band">
139	    <div class="wrap">
140	      <h2>Menu</h2>
141	      <ul>
142	        <li>Croissant <span class="price">$3.50</span></li>
143	        <li>Sourdough loaf <span class="price">$7.00</span></li>
144	        <li>Cinnamon roll <span class="price">$4.25</span></li>
145	      </ul>
146	    </div>
147	  </section>
148	
149	  <section id="order">
150	    <div class="wrap">
151	      <h2>Order</h2>
152	      <div class="order-grid">
153	        <button type="button" id="add-croissant">Add croissant<small>$3.50</small></button>
154	        <button type="button" id="add-sourdough">Add sourdough<small>$7.00</small></button>
155	        <button type="button" id="add-roll">Add cinnamon roll<small>$4.25</small></button>
156	      </div>
157	      <p class="tally">Items in your order: <span id="cart-count" aria-live="polite">0</span></p>
158	    </div>
159	  </section>
160	
161	  <section id="news" class="band">
162	    <div class="wrap">
163	      <h2>Newsletter</h2>
164	      <form id="news-form" novalidate>
165	        <input type="text" id="email" placeholder="your email" aria-label="Your email" autocomplete="email">
166	        <button type="submit">Subscribe</button>
167	      </form>
168	      <p id="news-msg" role="status"></p>
169	    </div>
170	  </section>
171	</main>
172	
173	<footer>
174	  <div class="wrap">Maple Street Bakery. Open 7am to 3pm, Tuesday to Sunday.</div>
175	</footer>
176	
177	<script>
178	var count = 0;
179	function addItem() {
180	  count = count + 1;
181	  document.getElementById("cart-count").textContent = count;
182	}
183	document.getElementById("add-croissant").onclick = addItem;
184	document.getElementById("add-sourdough").onclick = addItem;
185	document.getElementById("add-roll").onclick = addItem;
186	document.getElementById("news-form").onsubmit = function (e) {
187	  e.preventDefault();
188	  var v = document.getElementById("email").value;
189	  var msg = document.getElementById("news-msg");
190	  if (v.indexOf("@") === -1) { msg.textContent = "Please enter a valid email."; }
191	  else { msg.textContent = "Thanks for subscribing!"; }
192	};
193	
194	// Live open/closed status (Tue-Sun, 7am-3pm, visitor's local time)
195	(function () {
196	  var now = new Date(), d = now.getDay(), h = now.getHours();
197	  var el = document.getElementById("status");
198	  var open = d !== 1 && h >= 7 && h < 15;
199	  el.textContent = open ? "Open now until 3pm" : "Closed now. Open Tuesday to Sunday, 7am to 3pm";
200	  if (open) el.className = "status open";
201	})();
202	</script>
203	</body>
204	</html>
